<script setup lang="ts">
import {ref,computed,watch,onMounted,onBeforeUnmount} from 'vue';import {api,ApiError} from '../api';import type {WorkTab} from '../stores';import Modal from '../components/Modal.vue';
const props=defineProps<{tab:WorkTab;embedded?:boolean}>();const emit=defineEmits<{saved:[];close:[]}>();const data=ref<any>(null),selected=ref<string[]>([]),baseline=ref<string[]>([]),expected=ref<string[]>([]),query=ref(''),error=ref(''),message=ref(''),loading=ref(false),conflict=ref(false),confirm=ref<string[]|null>(null);let resolveConfirm:((ok:boolean)=>void)|null=null;
const user=computed(()=>data.value?.users.find((u:any)=>u.id===props.tab.recordId)||data.value?.assignments.find((a:any)=>a.user_id===props.tab.recordId)?.user);
const eligible=computed(()=>data.value?.users.some((u:any)=>u.id===props.tab.recordId));
const stores=computed(()=>(data.value?.stores||[]).filter((s:any)=>s.is_active||baseline.value.includes(s.id)).sort((a:any,b:any)=>a.store_code.localeCompare(b.store_code,'zh-Hant',{numeric:true})).filter((s:any)=>(s.store_code+' '+s.store_name).toLowerCase().includes(query.value.toLowerCase())));
const label=(id:string)=>{const s=data.value?.stores.find((s:any)=>s.id===id);return s?s.store_code+' '+s.store_name:id;};
const key=(ids:string[])=>[...ids].sort().join(',');watch(selected,()=>{props.tab.dirty=key(selected.value)!==key(baseline.value);message.value='';},{deep:true,flush:'sync'});
async function load(preserve=false){loading.value=true;error.value='';try{const result=await api('store-managers');data.value=result;const rows=result.assignments.filter((a:any)=>a.user_id===props.tab.recordId);baseline.value=rows.map((a:any)=>a.store_id);expected.value=rows.map((a:any)=>a.id+':'+a.store_id).sort();if(!preserve)selected.value=[...baseline.value];props.tab.dirty=key(selected.value)!==key(baseline.value);conflict.value=false;}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
function answer(ok:boolean){confirm.value=null;resolveConfirm?.(ok);resolveConfirm=null;}
async function save(){if(props.tab.busy||loading.value||!data.value||conflict.value)return false;if(!props.tab.dirty)return true;const removed=baseline.value.filter(id=>!selected.value.includes(id));if(removed.length){if(confirm.value)return false;const ok=await new Promise<boolean>(resolve=>{resolveConfirm=resolve;confirm.value=removed;});if(!ok)return false;}
props.tab.busy=true;error.value='';const ids=[...selected.value];try{await api('store-managers',{method:'PUT',body:JSON.stringify({userId:props.tab.recordId,storeIds:ids,expected:expected.value})});baseline.value=[...ids];props.tab.dirty=false;await load();if(error.value){message.value='指派已儲存，但最新資料讀取失敗。請重新載入後再編輯。';conflict.value=true;}else message.value='店長指派已儲存';emit('saved');return true;}catch(e){error.value=(e as Error).message;conflict.value=e instanceof ApiError&&e.status===409;return false;}finally{props.tab.busy=false;}}
props.tab.save=save;onBeforeUnmount(()=>{answer(false);delete props.tab.save;});onMounted(()=>load());
</script>
<template><header class="page-heading" :class="{embedded}"><div><p v-if="!embedded" class="eyebrow">組織與門市 / 店長指派</p><h1 v-if="!embedded">{{user?.full_name||user?.employee_code||'店長'}}的管理門市</h1><p class="muted">{{user?.employee_code}} {{user?.job_title}}</p></div><button :disabled="tab.busy||loading||!!confirm" @click="load(tab.dirty)">{{tab.dirty?'重新載入（保留目前選擇）':'重新載入'}}</button></header><p v-if="error" role="alert" class="notice error">{{error}}</p><p v-if="message" role="status" class="notice">{{message}}</p><p v-if="conflict" class="notice">請重新載入最新指派；目前勾選會保留，請核對後再儲存。</p><p v-if="loading" role="status">載入指派資料…</p><template v-else-if="data"><p v-if="!eligible" class="notice">此人員目前不符合新增指派資格，仍可解除既有指派。</p><p>目前選擇 {{selected.length}} 間門市</p><label class="store-search">搜尋門市<input v-model="query" placeholder="門市代碼或名稱"></label><fieldset :disabled="tab.busy||conflict||!!confirm"><legend>管理門市（可複選）</legend><label v-for="s in stores" :key="s.id" class="store-choice"><input type="checkbox" v-model="selected" :value="s.id" :disabled="(!eligible||!s.is_active)&&!baseline.includes(s.id)"><span>{{s.store_code}} {{s.store_name}}<small v-if="!s.is_active">（已停用，僅保留或解除既有指派）</small></span></label><p v-if="!stores.length" class="muted">沒有符合條件的門市</p></fieldset><section><h2>已選門市</h2><ul><li v-for="id in selected" :key="id">{{label(id)}} <button :disabled="tab.busy||conflict||!!confirm" @click="selected=selected.filter(s=>s!==id)">解除此門市</button></li></ul><p v-if="!selected.length" class="muted">未選擇門市；儲存後將解除此人員全部主要店長指派。</p><button :disabled="tab.busy||conflict||!!confirm||!selected.length" @click="selected=[]">解除全部指派</button></section></template><div class="dialog-actions"><button v-if="embedded" :disabled="tab.busy||!!confirm" @click="emit('close')">關閉</button><button class="primary" :disabled="tab.busy||loading||!data||conflict||!!confirm||!tab.dirty" @click="save">{{tab.busy?'儲存中…':'儲存指派'}}</button></div><Modal v-if="confirm" title="確認解除門市指派" @cancel="answer(false)"><p>儲存後，{{user?.full_name||'此人員'}}將解除以下門市的主要店長指派，可能影響門市存取權限：</p><ul><li v-for="id in confirm" :key="id">{{label(id)}}</li></ul><div class="dialog-actions"><button @click="answer(false)">返回編輯</button><button class="danger" @click="answer(true)">確認儲存指派</button></div></Modal></template>
<style scoped>.embedded{margin-bottom:12px;gap:12px}.embedded p{margin:0}.embedded + p{margin-top:8px}fieldset{max-height:38dvh;overflow:auto}.dialog-actions{position:sticky;bottom:-1px;background:var(--surface);padding:12px 0;}.store-search{display:grid;gap:8px;max-width:420px}fieldset{margin:24px 0;padding:16px;border:1px solid var(--line)}.store-choice{display:flex;align-items:center;gap:12px;padding:12px;border-bottom:1px solid var(--line)}.store-choice input{min-width:18px;min-height:18px;width:18px;height:18px}.store-choice small{display:block;color:var(--muted)}section h2{font-size:16px}section li{padding:8px 0}section li button{margin-left:10px}</style>
